--
-- Tabellenstruktur für Tabelle `rezept`
--

CREATE TABLE `rezept` (
  `rezept_id` int(11) NOT NULL,
  `titel` varchar(255) NOT NULL,
  `user_id` int(11) NOT NULL,
  `zubereitung` text NOT NULL,
  `zubereitungsdauer` int(11) NOT NULL,
  `portionen` int(11) NOT NULL,
  `ernaehrung` enum('Vegan','Vegetarisch','Normal','Fleisch','Fisch') NOT NULL,
  `schwierigkeitsgrad` enum('Leicht','Mittel','Schwer') NOT NULL,
  `mahlzeitkategorie` enum('Frühstück','Mittagessen','Abendessen','Dessert','Snack') NOT NULL,
  `kueche` enum('Amerikanisch','Italienisch','Indisch','Asiatisch','Orientalisch','Deutsch') NOT NULL,
  `bild` longblob DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Daten für Tabelle `rezept`
--

INSERT INTO `rezept` (`rezept_id`, `titel`, `user_id`, `zubereitung`, `zubereitungsdauer`, `portionen`, `ernaehrung`, `schwierigkeitsgrad`, `mahlzeitkategorie`, `kueche`, `bild`) VALUES
(1, 'Kürbissuppe ', 1, 'Kürbis waschen, halbieren, vierteln und die Kerne mit einem Esslöffel herausschaben. Fruchtfleisch in etwa daumengroße Stücke schneiden. Zwiebel schälen und würfeln. Knoblauch schälen und hacken.\r\nButter in einem Topf schmelzen. Zwiebel und Knoblauch darin glasig dünsten. Kürbis zufügen und kurz mitdünsten. Mit Brühe ablöschen und mit Salz und Pfeffer würzen. Zugedeckt bei milder Hitze ca. 15 Minuten köcheln lassen.\r\nCa. 3/4 der Sahne zufügen und alles fein pürieren. Noch einmal abschmecken. Suppe mit Rest Sahne und nach Belieben mit Pfeffer, gehackter Petersilie und Chiliflocken anrichten und servieren. Zur Kürbissuppe schmeckt frisches Baguette.', 40, 4, 'Vegetarisch', 'Leicht', 'Mittagessen', 'Deutsch', );
INSERT INTO `rezept` (`rezept_id`, `titel`, `user_id`, `zubereitung`, `zubereitungsdauer`, `portionen`, `ernaehrung`, `schwierigkeitsgrad`, `mahlzeitkategorie`, `kueche`, `bild`) VALUES
(2, 'American Cookies ', 1, 'Butter und Zucker mit dem Handmixer 3 Minuten schaumig rühren. Die Eier hinzugeben und weitere 3 min rühren, bis es noch cremiger ist.\r\nIn einer separaten Schüssel Mehl, Natron und Salz mischen und anschließend zur Buttermischung geben und mit einem Löffel unterrühren, bis gerade so ein Teig entsteht.\r\nAuf keinen Fall einen Handmixer hierfür verwenden und das Rühren mit dem Löffel nicht übertreiben. Der Teig ist perfekt, wenn gerade so kein Mehl mehr zu sehen ist. Die Schokolade unterheben.\r\n\r\nEin Backblech mit zwei Lagen Backpapier auslegen. Den Backofen auf 190°C Umluft vorheizen.\r\nZwetschgengroße Teighäufchen auf das Backpapier geben und diese leicht andrücken. Sie sollen gleich groß sein, damit sie gleichmäßig backen. Beim Backen laufen sie auseinander und bilden perfekte Kreise.\r\n10-13 min backen. Die Kekse sind noch extrem weich, wenn man sie aus dem Backofen holt - das ist aber normal. Beim Abkühlen sind die Kekse anfangs noch leicht gewölbt, fallen dann aber nach ein paar Minuten ein und bilden dabei diesen leckeren weichen Kekskern, wie er bei Subway so berühmt ist. Ich lasse meine Kekse 20 Minuten abkühlen.\r\n\r\nTipp:\r\nStatt Chocolate Chips kann man beliebige andere Zutaten unterheben. Die Zutaten dann grob hacken und in den Teig geben.', 30, 12, 'Vegetarisch', 'Leicht', 'Snack', 'Amerikanisch', );
INSERT INTO `rezept` (`rezept_id`, `titel`, `user_id`, `zubereitung`, `zubereitungsdauer`, `portionen`, `ernaehrung`, `schwierigkeitsgrad`, `mahlzeitkategorie`, `kueche`, `bild`) VALUES
(3, 'Lasagne', 1, 'Ragú Bolognese:\r\nIn einem Topf das Olivenöl erhitzen, das Hackfleisch darin rundherum anbraten und die gehackten Zwiebeln und die gehackte Petersilie dazugeben. Knoblauch in feinen Scheiben und Tomatenmark dazu rühren und mitbraten. Mit den Dosentomaten aufgießen, salzen und pfeffern. Rotwein nach Belieben beifügen. Das Ragú mindestens eine halbe Stunde lang bei geöffnetem Topf einkochen lassen.\r\n\r\nBéchamelsauce:\r\nButter in einem kleinen Topf schmelzen und das Mehl mit dem Schneebesen unterrühren und hellgelb anschwitzen. Die Milch dazugießen und die Sauce glatt rühren. Wer zu langsam gerührt hat und Klümpchen in der Sauce findet, kann die Sauce durch ein feines Haarsieb passieren und dann weiterkochen lassen. Die Sauce sollte fast eine halbe Stunde lang auf kleiner Flamme köcheln, damit sie den Mehlgeschmack verliert. Mit Salz, Pfeffer und Zitronensaft sowie etwas Muskatnuss abschmecken.\r\n\r\nZubereitung der Lasagne:\r\nIn einer gebutterten, feuerfesten Form etwas Ragú Bolognese verteilen, eine Schicht Lasagneplatten darauf legen, die Nudelschicht wieder mit Ragú und dann mit einer Schicht Béchamel bedecken.\r\nAnschließend wieder eine Schicht Nudeln, Ragú und Béchamel. So Schicht für Schicht die Form füllen.\r\nDie letzte Schicht sollte die Béchamelsauce bilden. Dick mit geriebenem Käse bestreuen und Butterflöckchen darauf setzen.\r\n\r\nDie Lasagne im heißen Backofen bei 180 °C Umluft ca. 30 - 40 Minuten backen, bis die Kruste goldbraun ist.\r\n\r\nTipp:\r\nDie Lasagne kann man auch gut einen Tag vorher vorbereiten und im Kühlschrank ziehen lassen.', 30, 4, 'Fleisch', 'Mittel', 'Mittagessen', 'Italienisch', );
INSERT INTO `rezept` (`rezept_id`, `titel`, `user_id`, `zubereitung`, `zubereitungsdauer`, `portionen`, `ernaehrung`, `schwierigkeitsgrad`, `mahlzeitkategorie`, `kueche`, `bild`) VALUES
(4, 'Rindergulasch', 1, 'In etwas Butterschmalz das Rindergulasch scharf anbraten. Nachdem es rundum angebraten ist, Zwiebeln, Knoblauch und die in Scheiben geschnittenen Karotten beifügen. Danach Tomatenmark zugeben und ca. 3 Minuten köcheln (Hitze etwas reduzieren). Dann mit dem Rotwein ablöschen und anschließend die Rinderbrühe und die Gemüsebrühe zugeben und mit Salz, Pfeffer und Paprikapulver würzen. Zugedeckt bei geringer Hitze ca. 1-1,5 Stunden schmoren. Zum Schluss sollte die Soße noch mit kalter Butter oder Saucenbinder angedickt werden.\r\n\r\nDazu passen hervorragend Kartoffelklöße, böhmische Knödel oder selbst gemachte Spätzle und natürlich Rotkraut und Salat.\r\n', 20, 4, 'Fleisch', 'Mittel', 'Mittagessen', 'Deutsch', );
INSERT INTO `rezept` (`rezept_id`, `titel`, `user_id`, `zubereitung`, `zubereitungsdauer`, `portionen`, `ernaehrung`, `schwierigkeitsgrad`, `mahlzeitkategorie`, `kueche`, `bild`) VALUES
(5, 'Schneller Pfannkuchenteig', 1, 'Die Eier mit dem Zucker cremig aufschlagen, dann mit der Milch verrühren. Nun Salz, Mehl und Backpulver dazugeben und alles zu einem glatten Teig rühren. Danach ist es von Vorteil, den Teig etwas ruhen zu lassen, da das Mehl noch ausquillt. Dann 1 - 2 große Schöpfkellen Teig in eine auf mittlere Hitze erhitzte, beschichtete Pfanne geben. Nach ca. 2 Minuten bilden sich kleine Bläschen, dann den Pfannkuchen einmal wenden und von der anderen Seite schön goldbraun ausbacken.', 5, 2, 'Vegetarisch', 'Leicht', 'Frühstück', 'Amerikanisch', );
INSERT INTO `rezept` (`rezept_id`, `titel`, `user_id`, `zubereitung`, `zubereitungsdauer`, `portionen`, `ernaehrung`, `schwierigkeitsgrad`, `mahlzeitkategorie`, `kueche`, `bild`) VALUES
(6, 'Tagliatelle al Salmone', 1, 'Zunächst den Lachs würfeln und im Olivenöl rundum kurz anbraten, dann herausnehmen.\r\n\r\nDie gehackten Schalotten in die Pfanne geben. Kurz anschwitzen, bis sie glasig sind. Dann zwei Knoblauch hineinpressen und direkt mit dem Weißwein ablöschen. Nun den Wein bis zur Hälfte reduzieren und dann die Gemüsebrühe dazugeben. Dies nun ca. weitere 5 Minuten zusammen köcheln lassen.\r\n\r\nAnschließend die Dosentomaten und das Tomatenmark beifügen. Ordentlich mit Salz und Pfeffer würzen. Den Saft der halben Limette dazugeben, die Soße abschmecken und evtl. nach Belieben noch eine Zehe Knoblauch hineinpressen. Nach ca. 5 Minuten die Sahne darüber gießen und dann den Lachs wieder in die Soße legen. Nochmal kurz aufkochen lassen, dann die zwischenzeitlich gekochten Tagliatelle in die Sauce geben und kurz darin ziehen lassen, damit sie etwas Sauce aufnehmen können.\r\n\r\nDill und Petersilie darüber streuen und mit etwas Fleur de Sel bestreut servieren.', 25, 4, 'Fisch', 'Mittel', 'Abendessen', 'Italienisch', );
INSERT INTO `rezept` (`rezept_id`, `titel`, `user_id`, `zubereitung`, `zubereitungsdauer`, `portionen`, `ernaehrung`, `schwierigkeitsgrad`, `mahlzeitkategorie`, `kueche`, `bild`) VALUES
(7, 'Avocado-Gurke-Kichererbsensalat mit Feta und Zitronendressing', 1, 'Die Tomaten halbieren, die Kichererbsen abtropfen und abspülen, die Gurke in kleine Viertel schneiden, die Avocados entkernen und in Stücke schneiden, die Petersilie klein hacken und alles in eine Salatschüssel geben und vorsichtig mischen.\r\n\r\nFür das Dressing Olivenöl, Zitronensaft, Dijonsenf, Knoblauch und Salz mit einem Pürierstab zu einer sämigen Soße mixen. Basilikum und Oregano einrühren (nicht mehr mixen!) und über den Salat geben.\r\n\r\nDen Salat mit dem Dressing mischen und mind. 1 Stunde ziehen lassen.\r\n\r\nVor dem Servieren den Feta zerbröseln und darüber geben.', 20, 2, 'Vegetarisch', 'Leicht', 'Snack', 'Deutsch', );
INSERT INTO `rezept` (`rezept_id`, `titel`, `user_id`, `zubereitung`, `zubereitungsdauer`, `portionen`, `ernaehrung`, `schwierigkeitsgrad`, `mahlzeitkategorie`, `kueche`, `bild`) VALUES
(8, 'Knusprige Curry-Rosmarin-Ofenkartoffeln', 1, 'Die geschälten, geviertelten Kartoffeln gut mit Küchenkrepp abtrocknen. Die Kartoffeln in eine große Schale geben, die Gewürze dazugeben und alles gut mit den Händen durchmengen. Nun das Öl dazugeben und nochmals durchmengen. Die Kartoffeln auf ein Blech geben. Ich fette das Blech nicht noch zusätzlich ein, da das Öl an den Kartoffeln bereits genügt.\r\n\r\nIm vorgeheizten Backofen bei 200 °C Ober-/Unterhitze auf mittlerer Schiene ca. 30 - 40 Min. (je nach Größe der Kartoffelspalten) backen.\r\n\r\nAlle 10 Min. müssen die Spalten gewendet werden, damit sie von allen Seiten schön kross werden. Wenn die Spalten anfangs etwas am Blech festbacken - nicht schlimm, einfach mit einem Pfannenwender lösen.', 20, 4, 'Vegan', 'Leicht', 'Snack', 'Orientalisch', );
INSERT INTO `rezept` (`rezept_id`, `titel`, `user_id`, `zubereitung`, `zubereitungsdauer`, `portionen`, `ernaehrung`, `schwierigkeitsgrad`, `mahlzeitkategorie`, `kueche`, `bild`) VALUES
(9, 'Himbeersorbet', 1, 'Den Zucker mit 100 ml Wasser aufkochen lassen, 5 Minuten köcheln lassen und danach abkühlen lassen.\r\n\r\nDie Himbeeren mit Zitronensaft pürieren und danach durch ein Sieb passieren. Den Zuckersirup unter das Himbeerpüree rühren.\r\n\r\nFür mindestens 4 Stunden in den Gefrierschrank geben und nach jeder vollen Stunde mit einer Gabel umrühren.', 16, 2, 'Vegan', 'Leicht', 'Dessert', 'Italienisch', );
INSERT INTO `rezept` (`rezept_id`, `titel`, `user_id`, `zubereitung`, `zubereitungsdauer`, `portionen`, `ernaehrung`, `schwierigkeitsgrad`, `mahlzeitkategorie`, `kueche`, `bild`) VALUES
(10, 'Leckere Falafel', 1, 'Die Kichererbsen in einer Schüssel mit reichlich kaltem Wasser bedecken und 12 Stunden quellen lassen. Anschließend abtropfen lassen. Das Brot zerkrümeln. Zwiebel und Knoblauch schälen und grob zerkleinern. Petersilie waschen und die Blättchen abzupfen. Brot, Zwiebel, Knoblauch, Petersilie und Kichererbsen im Mixer fein zerkleinern.\r\n\r\nDas Püree mit Koriander, Kreuzkümmel, Pfeffer und Salz abschmecken und mit Mehl und Backpulver verkneten. Aus dem Teig walnussgroße Bällchen formen.\r\n\r\nDas Öl zum Frittieren erhitzen. Es ist heiß genug, wenn an einem hölzernen Kochlöffelstiel, den man ins Fett hält, viele Bläschen aufsteigen. Die Falafel darin portionsweise in 4 - 5 Minuten goldbraun frittieren. Jeweils auf einer dicken Lage Küchenpapier abtropfen lassen.\r\n\r\nDie Zitrone in Schnitze schneiden und die heißen Falafel damit servieren.', 60, 2, 'Vegan', 'Schwer', 'Snack', 'Orientalisch', );
INSERT INTO `rezept` (`rezept_id`, `titel`, `user_id`, `zubereitung`, `zubereitungsdauer`, `portionen`, `ernaehrung`, `schwierigkeitsgrad`, `mahlzeitkategorie`, `kueche`, `bild`) VALUES
(11, 'Einfacher Schweinebraten', 1, 'Den Schweinebraten im Bräter in Olivenöl von allen Seiten scharf anbraten. Dann das Fleisch herausnehmen und die Zwiebeln im Öl anrösten. In der Zeit den Schweinebraten mit Senf einstreichen, salzen und pfeffern.\r\n\r\nWenn die Zwiebeln goldgelb sind, das Fleisch zurück in den Bräter legen und die Zwiebeln darauf legen. Nach Belieben auch Knoblauchzehen halbieren und dazugeben. Das Wasser angießen, den Bräter zudecken und für 60-75 Minuten bei 170 Grad Umluft in den Backofen stellen.\r\n\r\nWenn das Fleisch weich ist, herausnehmen und die Sauce in einen Topf geben. Es wird nicht sehr viel Sauce sein, aber dafür ist sie kräftig. Aufkochen lassen, evtl. den Knoblauch herausfischen und die Sauce pürieren. Nach Belieben etwas binden.\r\n\r\n', 15, 3, 'Fleisch', 'Mittel', 'Abendessen', 'Deutsch', );
INSERT INTO `rezept` (`rezept_id`, `titel`, `user_id`, `zubereitung`, `zubereitungsdauer`, `portionen`, `ernaehrung`, `schwierigkeitsgrad`, `mahlzeitkategorie`, `kueche`, `bild`) VALUES
(12, 'Knoblauch-Champignons', 1, 'Die Champignons mit einem Tuch abreiben.\r\n\r\nDas Olivenöl in einer gusseisernen Pfanne erhitzen. Den Knoblauch darin 30 - 60 Sekunden leicht bräunen.\r\n\r\nDie Champignons dazugeben und rühren, bis die Pilze das gesamte Öl aufgenommen haben. Auf schwacher Hitze weitergaren, bis sie den Saft abgeben, dann weiterrühren (4 - 5 Minuten), bis der Saft verdampft ist. Zitronensaft, Salz, Pfeffer und Petersilie unterrühren.', 20, 2, 'Vegan', 'Leicht', 'Snack', 'Italienisch', );
INSERT INTO `rezept` (`rezept_id`, `titel`, `user_id`, `zubereitung`, `zubereitungsdauer`, `portionen`, `ernaehrung`, `schwierigkeitsgrad`, `mahlzeitkategorie`, `kueche`, `bild`) VALUES
(13, 'Pimientos de Padron', 2, 'Die Paprika waschen, Olivenöl in einem Topf erhitzen und die Paprika darin rundum braten, bis die Haut Blasen wirft, ein paar dunkle Stellen schaden nicht. Auf einem Teller anrichten, mit Fleur de Sel bestreuen und sofort servieren.\r\n\r\nDas ist eine schnell zubereitete, leckere Tapa die zusammen mit Patates Braves, Serranoschinken, Manchego, etc. gegessen wird.\r\n\r\nDa die Paprika beim Braten stark spritzen, ist es von Vorteil, zum Braten einen höheren Topf statt einer Pfanne zu nehmen.\r\n', 10, 2, 'Vegan', 'Leicht', 'Snack', 'Italienisch', );
INSERT INTO `rezept` (`rezept_id`, `titel`, `user_id`, `zubereitung`, `zubereitungsdauer`, `portionen`, `ernaehrung`, `schwierigkeitsgrad`, `mahlzeitkategorie`, `kueche`, `bild`) VALUES
(14, 'Saftiges Butter-Rührei \'Profi Klasse\'', 2, 'Es kommt hier im Besonderen auf Temperaturen, Technik der Zutatenvermengung und Ablauf an!\r\n\r\nBereitstellen: 2 Müslischüsseln, eine davon fürs fertige Rührei leicht vorwärmen. 1 kleine Schüssel für die zu schmelzende Butter.\r\n\r\nDie Pfanne sehr stark vorheizen - genau timen bis zum Start. Die Pfanne beim Erhitzen mit einem 5-Markstück-großen Klecks Olivenöl versehen und diesen sofort mit einem Küchenpapier großzügig bis zum obersten Rand verreiben - überall muss kräftig Öl glänzen. Weiter erhitzen, wirklich sehr sehr heiß.\r\n\r\nVorbereitung der Eier: Ganz einfach, aber mit Trick! Wir wollen hier ein Butteraroma wie in den besten Restaurants, richtig? Jedoch hat Butter die Eigenschaft, schnell zu verbrennen - dennoch soll das echte Aroma her. Gleichzeitig soll die Konsistenz saftig sein und das Eigelb neben der Flüssigkeit der Butter ebenfalls noch einen Hauch Flüssigglanz beibehalten, richtig?\r\n\r\nDazu die 4 Eier in eine Müslischüssel geben, dazu eine Prise Fleur de Sel (kurz fein gemahlen), einen kleinen Hauch frisch geschnittenen Schnittlauch (nur ca. 1 Halm in feinen Röllchen, maximal 2 Halme) und evtl. einen halben Gewürzmühlendreher schwarzen Pfeffers.\r\n\r\nParallel dazu das Stückchen Butter in einem kleinen Schälchen in der Mikrowelle bei 150 Watt zum Schmelzen bringen. Dabei zuschauen, nur leicht schmelzen.\r\n\r\nJetzt kommt\'s: Die flüssige Butter bei kräftigem Schlagen zu den Eiern geben, sodass sich das Rührei schon vor der Pfanne mit der Butter verbindet. Die Butter kommt also nur kurz mit der sehr heißen Pfanne in Berührung, ihr volles Aroma kann sich entfalten, aber sie brennt nicht an!\r\n\r\nDie Technik des Erstarrens in der Pfanne - es kommt exakt auf die Sekunde an:\r\n\r\nEine für die Pfanne nicht zu große Menge der Eier in der Nähe des Griffes eingießen - es zischt, ein Teil erstarrt sofort von unten. Die Pfanne mit der Hand am Griff etwas hochheben und neigen, damit sich die restliche Flüssigkeit entlang der Schräge nach unten über den weiteren heißen Pfannenboden ergießt, gleichzeitig mit einem Holzspatel in der anderen Hand die sich leicht ablösende, erstarrte Masse in krausen Falten sofort die Schräge hoch zum Pfannenrand ziehen. Die dabei weiter nach unten fließende Masse erstarrt parallel wieder ebenso schnell. Auch diese sofort wieder in krausen Falten mit dem Spatel die Schräge hinaufziehen. Dieser Abschnitt dauert nur ca. 5 Sekunden, wenn die Pfanne heiß genug ist!\r\n\r\nIst die erstarrte, krause Masse bereits gut und nicht zu saftig - sofort raus damit in die vorgewärmte Müslischüssel. Was noch zu flüssig ist, kurz innerhalb einer einzigen Sekunde so eben noch einmal gewendet und mit glänzender Oberfläche raus aus der Pfanne! Schnell raus, ausschütten oder mit dem Spatel rasch aushebeln! Der Trick: Das Ei ist so heiß, dass es in der Schüssel noch etwas nachgart.\r\n\r\nBei einer größeren Pfanne kann man dies mit dem gesamten Ei so durchführen, bei einer kleineren nur mit einem Teil, der Vorgang muss dann mit dem restlichen Ei so oft wiederholt werden, bis man in der fertigen Schüssel ein saftiges Butterrührei präsentieren kann - dieses muss sofort auf den Tisch.\r\n\r\nWeiterer Trick: Wer mag, schüttet das fertige JetSet Rührei der Spitzenklasse wieder zurück in die nun leere Müslischüssel der rohen Eiermasse - das Eigelb dort verleiht zusätzliche Saftigkeit, wird jedoch ausreichend vom Rührei erhitzt.\r\n\r\nFazit: Es muss alles superschnell gehen. Die Konsistenz wird in Folge (positiv gemeint) leicht lappig und mehrlagig leicht zusammenhängend. Die Oberfläche des Eies wird dadurch sehr saftig - ist aber dennoch gefahrlos \'durch\'.\r\n\r\nDie Saftigkeit und der Glanz resultieren aus der gebundenen Butter im Ei und kleinen Resten des an der Oberfläche nicht ganz erstarrten Eigelbes. Zum Vergleich: Ganz genau so, wie beim Eierkochen oftmals ein sogenanntes wachsweiches Eigelb gewünscht wird, das ebenfalls als Kunstgriff nicht ganz fest ist. Die hohe Pfannentemperatur und das \'Nachreifen\' der Masse in der Schüssel verhindern hier erfolgreich, dass das Rührei zu fest, trocken oder bröselig wird.\r\n\r\nEin unglaublicher Aufwand an Präzision für so ein einfaches Stück Natur - ein hochwertiges Grundelement bis zum Geht-nicht-mehr optimiert!', 20, 2, 'Vegetarisch', 'Mittel', 'Frühstück', 'Amerikanisch', );

